@icontract.ensure(lambda nums, OLD: tuple(nums) == OLD.nums_before)
@icontract.ensure(lambda rems, OLD: tuple(rems) == OLD.rems_before)
@icontract.ensure(lambda result: result >= 1)
@icontract.ensure(lambda result, OLD: all(result % n == r for n, r in zip(OLD.nums_before, OLD.rems_before)))
@icontract.ensure(lambda result, OLD: all(any(y % n != r for n, r in zip(OLD.nums_before, OLD.rems_before)) for y in range(1, result)))

@icontract.snapshot(lambda nums: tuple(nums), name="nums_before")
@icontract.snapshot(lambda rems: tuple(rems), name="rems_before")
@icontract.ensure(lambda OLD, nums: tuple(nums) == OLD.nums_before)
@icontract.ensure(lambda OLD, rems: tuple(rems) == OLD.rems_before)
@icontract.ensure(lambda result: result >= 1)
@icontract.ensure(lambda result, nums, rems: all((result % nums[i]) == rems[i] for i in range(len(nums))))
@icontract.ensure(lambda nums, rems: all(0 <= rems[i] < nums[i] for i in range(len(nums))))
@icontract.ensure(lambda result, nums, rems: all(any((y % nums[i]) != rems[i] for i in range(len(nums))) for y in range(1, result)))
